import Foundation
import CoreML
import Combine
import Accelerate

class InferenceEngine: ObservableObject {
    let decoder: CTCDecoder
    
    // CoreML Model instances (Auto-generated by Xcode when mlpackage is added to target)
    private var acousticModel: Wav2Vec2_STT!
    var phonemeEngine: PhonemeInferenceEngine?
    
    @Published var latestTranscript: String = ""
    @Published var latestLiteralTranscript: String = ""
    @Published var latestFormattedTranscript: String = ""
    @Published var isProcessing: Bool = false
    @Published var wordTimestamps: [WordTimestamp]? = nil
    
    enum ModelState: Equatable {
        case loading
        case ready
        case failed(String)
    }
    
    @Published var modelState: ModelState = .loading
    @Published var useLearnedScoringHead: Bool = true
    @Published var useLearnedConfidenceHead: Bool = true
    public private(set) var latestHiddenStates: MLMultiArray? = nil
    @Published public private(set) var latestLogProbs: [[Float]]? = nil
    @Published public private(set) var latestTopBeams: [String] = []
    private let acousticLock = NSLock()
    private let phonemeLock = NSLock()
    
    init(decoder: CTCDecoder, synchronousLoad: Bool = false) {
        self.decoder = decoder
        
        if synchronousLoad {
            do {
                let config = MLModelConfiguration()
                config.computeUnits = .cpuOnly
                self.acousticModel = try Wav2Vec2_STT(configuration: config)
                
                if let modelURL = Bundle.main.url(forResource: "Wav2Vec2_Phonetic", withExtension: "mlmodelc") {
                    let w2vConfig = MLModelConfiguration()
                    w2vConfig.computeUnits = .cpuAndGPU
                    let w2vModel = try MLModel(contentsOf: modelURL, configuration: w2vConfig)
                    self.phonemeEngine = PhonemeInferenceEngine(model: w2vModel)
                }
                
                self.modelState = .ready
            } catch {
                print("CRITICAL ERROR: Failed to load CoreML models. \(error)")
                self.modelState = .failed(error.localizedDescription)
            }
        } else {
            // Load the CoreML models asynchronously on background thread, then update state on MainActor
            Task { @MainActor [weak self] in
                do {
                    let (model, w2vEngine) = try await Task.detached(priority: .userInitiated) { () -> (Wav2Vec2_STT, PhonemeInferenceEngine?) in
                        let config = MLModelConfiguration()
                        config.computeUnits = .cpuOnly
                        let acoustic = try await Wav2Vec2_STT.load(configuration: config)
                        
                        var phonetic: PhonemeInferenceEngine? = nil
                        if let modelURL = Bundle.main.url(forResource: "Wav2Vec2_Phonetic", withExtension: "mlmodelc") {
                            let w2vConfig = MLModelConfiguration()
                            w2vConfig.computeUnits = .cpuAndGPU
                            let w2vModel = try await MLModel.load(contentsOf: modelURL, configuration: w2vConfig)
                            phonetic = PhonemeInferenceEngine(model: w2vModel)
                        }
                        return (acoustic, phonetic)
                    }.value
                    
                    guard let strongSelf = self else { return }
                    strongSelf.acousticModel = model
                    strongSelf.phonemeEngine = w2vEngine
                    strongSelf.modelState = .ready
                } catch {
                    print("CRITICAL ERROR: Failed to load CoreML models. \(error)")
                    guard let strongSelf = self else { return }
                    strongSelf.modelState = .failed(error.localizedDescription)
                }
            }
        }
    }
    
    private var currentTask: Task<Void, Never>?
    
    private var lastLiveProcessTime: Date = Date()
    private var liveProcessTask: Task<Void, Never>? = nil
    
    func processLive(audioChunk: [Float]) {
        guard modelState == .ready else { return }
        let now = Date()
        if now.timeIntervalSince(lastLiveProcessTime) < 0.3 { return }
        lastLiveProcessTime = now
        
        liveProcessTask?.cancel()
        liveProcessTask = Task {
            let targetLength = 16000 * 5 // 5 seconds
            var totalLiteral = ""
            var totalSnapped = ""
            var offset = 0
            while offset < audioChunk.count {
                if Task.isCancelled { return }
                let validLength = min(targetLength, audioChunk.count - offset)
                var unpaddedChunk = Array(audioChunk[offset..<(offset + validLength)])
                
                var mean: Float = 0
                var stdDev: Float = 0
                vDSP_normalize(unpaddedChunk, 1, nil, 1, &mean, &stdDev, vDSP_Length(validLength))
                if stdDev > 1e-6 {
                    vDSP_normalize(unpaddedChunk, 1, &unpaddedChunk, 1, &mean, &stdDev, vDSP_Length(validLength))
                }
                
                guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: targetLength)], dataType: .float32) else { return }
                let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: targetLength)
                for i in 0..<targetLength {
                    ptr[i] = (i < validLength) ? unpaddedChunk[i] : 0.0
                }
                
                do {
                    let output = try await self.acousticModel.prediction(input: Wav2Vec2_STTInput(audio: mlArray))
                    let validFrames = min(249, max(1, Int(ceil(Double(validLength) / 320.0))))
                    let decodedText = self.decodeLogits(output.ctc_logits, validFrames: validFrames)
                    if !decodedText.literal.isEmpty { totalLiteral += (totalLiteral.isEmpty ? "" : " ") + decodedText.literal }
                    if !decodedText.snapped.isEmpty { totalSnapped += (totalSnapped.isEmpty ? "" : " ") + decodedText.snapped }
                } catch { print("Live inference error: \(error)") }
                offset += targetLength
            }
            if Task.isCancelled { return }
            await MainActor.run {
                if self.isProcessing { return }
                self.latestLiteralTranscript = totalLiteral
                self.latestTranscript = totalSnapped
            }
        }
    }

    private func mergeOverlappingTimestamps(_ t1: [WordTimestamp], _ t2: [WordTimestamp]) -> [WordTimestamp] {
        if t1.isEmpty { return t2 }
        if t2.isEmpty { return t1 }
        let w1 = t1.map { $0.word }
        let w2 = t2.map { $0.word }
        var maxOverlap = 0
        let maxPossible = min(w1.count, w2.count)
        for i in 1...maxPossible {
            let suffix = Array(w1.suffix(i))
            let prefix = Array(w2.prefix(i))
            if suffix == prefix { maxOverlap = i }
        }
        if maxOverlap > 0 {
            return t1 + Array(t2.dropFirst(maxOverlap))
        }
        return t1 + t2
    }

    func process(audioChunk: [Float], sfSpeechHint: String? = nil) {
        guard acousticModel != nil else { return }
        
        currentTask?.cancel()
        
        currentTask = Task {
            await MainActor.run { self.isProcessing = true }
            
            let targetLength = 16000 * 5 // 5 seconds
            
            if audioChunk.count <= targetLength {
                let validLength = audioChunk.count
                var unpaddedChunk = audioChunk
                
                var mean: Float = 0
                var stdDev: Float = 0
                vDSP_normalize(unpaddedChunk, 1, nil, 1, &mean, &stdDev, vDSP_Length(validLength))
                if stdDev > 1e-6 {
                    vDSP_normalize(unpaddedChunk, 1, &unpaddedChunk, 1, &mean, &stdDev, vDSP_Length(validLength))
                }
                
                guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: targetLength)], dataType: .float32) else { return }
                let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: targetLength)
                for i in 0..<targetLength {
                    ptr[i] = (i < validLength) ? unpaddedChunk[i] : 0.0
                }
                
                if Task.isCancelled { return }
                
                do {
                    let input = Wav2Vec2_STTInput(audio: mlArray)
                    let output = try await self.acousticModel.prediction(input: input)
                    if Task.isCancelled { return }
                    
                    let hs = output.hidden_states
                    let validFrames = min(249, max(1, Int(ceil(Double(validLength) / 320.0))))
                    let decodedText = self.decodeLogits(output.ctc_logits, validFrames: validFrames)
                    let timestamps = CTCSegmentation.align(
                        transcript: decodedText.snapped,
                        logProbs: decodedText.logProbs,
                        vocab: self.decoder.vocab,
                        blankIndex: self.decoder.blankIndex,
                        timeOffset: 0.0
                    )
                    
                    if Task.isCancelled { return }
                    
                    let formatted = PunctuationTransferEngine.shared.transferPunctuation(
                        acousticText: decodedText.snapped,
                        sfSpeechText: sfSpeechHint
                    )
                    
                    await MainActor.run {
                        self.latestHiddenStates = hs
                        self.latestLiteralTranscript = decodedText.literal
                        self.latestTranscript = decodedText.snapped
                        self.latestFormattedTranscript = formatted
                        self.wordTimestamps = timestamps
                        self.latestLogProbs = decodedText.logProbs
                        self.latestTopBeams = decodedText.topBeams
                        self.isProcessing = false
                    }
                    return
                } catch {
                    print("Inference error: \(error)")
                }
            }
            
            // Audio > 5.0 seconds: seamless acoustic stitching
            let step = Int(16000 * 4.0) // 4.0 second step = 200 frames
            let framesPerStep = 200
            var totalLogProbs: [[Float]] = []
            var lastHiddenStates: MLMultiArray? = nil
            
            var offset = 0
            while offset < audioChunk.count {
                let validLength = min(targetLength, audioChunk.count - offset)
                var unpaddedChunk = Array(audioChunk[offset..<(offset + validLength)])
                
                var mean: Float = 0
                var stdDev: Float = 0
                vDSP_normalize(unpaddedChunk, 1, nil, 1, &mean, &stdDev, vDSP_Length(validLength))
                if stdDev > 1e-6 {
                    vDSP_normalize(unpaddedChunk, 1, &unpaddedChunk, 1, &mean, &stdDev, vDSP_Length(validLength))
                }
                
                guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: targetLength)], dataType: .float32) else { return }
                let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: targetLength)
                for i in 0..<targetLength {
                    ptr[i] = (i < validLength) ? unpaddedChunk[i] : 0.0
                }
                
                if Task.isCancelled { return }
                
                do {
                    let input = Wav2Vec2_STTInput(audio: mlArray)
                    let output = try await self.acousticModel.prediction(input: input)
                    if Task.isCancelled { return }
                    lastHiddenStates = output.hidden_states
                    
                    let validFrames = min(249, max(1, Int(ceil(Double(validLength) / 320.0))))
                    let isLastChunk = offset + step >= audioChunk.count
                    let chunkLogProbs = self.extractLogProbs(output.ctc_logits, validFrames: validFrames)
                    
                    if isLastChunk {
                        totalLogProbs.append(contentsOf: chunkLogProbs)
                    } else {
                        let framesToKeep = min(chunkLogProbs.count, framesPerStep)
                        totalLogProbs.append(contentsOf: chunkLogProbs.prefix(framesToKeep))
                    }
                } catch {
                    print("Inference error: \(error)")
                }
                
                offset += step
            }
            
            if Task.isCancelled { return }
            
            let decoded = self.decoder.decode(logProbs: totalLogProbs, beamWidth: 30)
            let timestamps = CTCSegmentation.align(
                transcript: decoded.snapped,
                logProbs: totalLogProbs,
                vocab: self.decoder.vocab,
                blankIndex: self.decoder.blankIndex,
                timeOffset: 0.0
            )
            
            if Task.isCancelled { return }
            
            let formatted = PunctuationTransferEngine.shared.transferPunctuation(
                acousticText: decoded.snapped,
                sfSpeechText: sfSpeechHint
            )
            
            await MainActor.run {
                self.latestHiddenStates = lastHiddenStates
                self.latestLiteralTranscript = decoded.literal
                self.latestTranscript = decoded.snapped
                self.latestFormattedTranscript = formatted
                self.wordTimestamps = timestamps
                self.latestLogProbs = totalLogProbs
                self.latestTopBeams = decoded.topBeams
                self.isProcessing = false
            }
        }
    }
    
    func processSynchronously(audioChunk: [Float], reference: String? = nil) -> (snapped: String, literal: String, wordTimestamps: [WordTimestamp], logProbs: [[Float]], hiddenStates: MLMultiArray?, topBeams: [String])? {
        guard acousticModel != nil else { return nil }
        
        let targetLength = 16000 * 5 // 5 seconds = 80,000 samples
        
        // Single-pass for audio <= 5.0 seconds (84.9% of dataset)
        if audioChunk.count <= targetLength {
            let validLength = audioChunk.count
            var unpaddedChunk = audioChunk
            
            var mean: Float = 0
            var stdDev: Float = 0
            vDSP_normalize(unpaddedChunk, 1, nil, 1, &mean, &stdDev, vDSP_Length(validLength))
            if stdDev > 1e-6 {
                vDSP_normalize(unpaddedChunk, 1, &unpaddedChunk, 1, &mean, &stdDev, vDSP_Length(validLength))
            }
            
            guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: targetLength)], dataType: .float32) else { return nil }
            let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: targetLength)
            for i in 0..<targetLength {
                ptr[i] = (i < validLength) ? unpaddedChunk[i] : 0.0
            }
            
            let hs: MLMultiArray
            let ctcLogits: MLMultiArray
            do {
                acousticLock.lock()
                let input = Wav2Vec2_STTInput(audio: mlArray)
                let output = try self.acousticModel.prediction(input: input)
                hs = output.hidden_states
                self.latestHiddenStates = hs
                ctcLogits = output.ctc_logits
                acousticLock.unlock()
            } catch {
                acousticLock.unlock()
                print("Inference failed: \(error)")
                return nil
            }
            
            let validFrames = min(249, max(1, Int(ceil(Double(validLength) / 320.0))))
            let decodedText = self.decodeLogits(ctcLogits, validFrames: validFrames, reference: reference)
            
            let alignTranscript = reference ?? decodedText.snapped
            let timestamps = CTCSegmentation.align(
                transcript: alignTranscript,
                logProbs: decodedText.logProbs,
                vocab: self.decoder.vocab,
                blankIndex: self.decoder.blankIndex,
                timeOffset: 0.0
            )
            
            return (snapped: decodedText.snapped, literal: decodedText.literal, wordTimestamps: timestamps, logProbs: decodedText.logProbs, hiddenStates: hs, topBeams: decodedText.topBeams)
        }
        
        // Multi-slice seamless acoustic stitching for audio > 5.0 seconds
        let step = Int(16000 * 4.0) // 4.0 second step = 200 frames
        let framesPerStep = 200
        var totalLogProbs: [[Float]] = []
        
        var offset = 0
        while offset < audioChunk.count {
            let validLength = min(targetLength, audioChunk.count - offset)
            var unpaddedChunk = Array(audioChunk[offset..<(offset + validLength)])
            
            var mean: Float = 0
            var stdDev: Float = 0
            vDSP_normalize(unpaddedChunk, 1, nil, 1, &mean, &stdDev, vDSP_Length(validLength))
            if stdDev > 1e-6 {
                vDSP_normalize(unpaddedChunk, 1, &unpaddedChunk, 1, &mean, &stdDev, vDSP_Length(validLength))
            }
            
            guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: targetLength)], dataType: .float32) else { return nil }
            let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: targetLength)
            for i in 0..<targetLength {
                ptr[i] = (i < validLength) ? unpaddedChunk[i] : 0.0
            }
            
            do {
                let input = Wav2Vec2_STTInput(audio: mlArray)
                let output = try self.acousticModel.prediction(input: input)
                self.latestHiddenStates = output.hidden_states
                
                let validFrames = min(249, max(1, Int(ceil(Double(validLength) / 320.0))))
                let chunkLogProbs = self.extractLogProbs(output.ctc_logits, validFrames: validFrames)
                
                if totalLogProbs.isEmpty {
                    totalLogProbs.append(contentsOf: chunkLogProbs)
                } else {
                    // Seamless acoustic stitching: Cross-fade overlapping frames (up to 49 frames / 1.0s)
                    let overlapFrames = min(49, min(chunkLogProbs.count, totalLogProbs.count))
                    let stitchIdx = totalLogProbs.count - overlapFrames
                    for i in 0..<overlapFrames {
                        let alpha = Float(i + 1) / Float(overlapFrames + 1)
                        let prevFrame = totalLogProbs[stitchIdx + i]
                        let nextFrame = chunkLogProbs[i]
                        let nVals = min(prevFrame.count, nextFrame.count)
                        var blended = [Float](repeating: 0, count: nVals)
                        for v in 0..<nVals {
                            blended[v] = (1.0 - alpha) * prevFrame[v] + alpha * nextFrame[v]
                        }
                        totalLogProbs[stitchIdx + i] = blended
                    }
                    if chunkLogProbs.count > overlapFrames {
                        totalLogProbs.append(contentsOf: chunkLogProbs[overlapFrames...])
                    }
                }
            } catch {
                print("Inference failed: \(error)")
                return nil
            }
            
            offset += step
        }
        
        let decoded = self.decoder.decode(logProbs: totalLogProbs, referenceText: reference, beamWidth: 30)
        let alignTranscript = reference ?? decoded.snapped
        let timestamps = CTCSegmentation.align(
            transcript: alignTranscript,
            logProbs: totalLogProbs,
            vocab: self.decoder.vocab,
            blankIndex: self.decoder.blankIndex,
            timeOffset: 0.0
        )
        
        return (snapped: decoded.snapped, literal: decoded.literal, wordTimestamps: timestamps, logProbs: totalLogProbs, hiddenStates: self.latestHiddenStates, topBeams: decoded.topBeams)
    }
    
    func extractPhonemeLogits(audioChunk: [Float]) -> MLMultiArray? {
        guard let phonemeEngine = phonemeEngine else { return nil }
        
        var normalizedAudio = audioChunk
        var mean: Float = 0
        var stdDev: Float = 0
        vDSP_normalize(normalizedAudio, 1, nil, 1, &mean, &stdDev, vDSP_Length(normalizedAudio.count))
        if stdDev > 1e-6 {
            vDSP_normalize(normalizedAudio, 1, &normalizedAudio, 1, &mean, &stdDev, vDSP_Length(normalizedAudio.count))
        }
        
        let numFrames = normalizedAudio.count
        guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: numFrames)], dataType: .float32) else { return nil }
        
        // We can copy directly to dataPointer for speed
        let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: numFrames)
        for i in 0..<numFrames {
            ptr[i] = normalizedAudio[i]
        }
        
        phonemeLock.lock()
        defer { phonemeLock.unlock() }
        return try? phonemeEngine.extractUserLogits(from: mlArray)
    }
    
    func extractSTTHiddenStates(audioChunk: [Float]) -> MLMultiArray? {
        var normalizedAudio = audioChunk
        var mean: Float = 0
        var stdDev: Float = 0
        vDSP_normalize(normalizedAudio, 1, nil, 1, &mean, &stdDev, vDSP_Length(normalizedAudio.count))
        if stdDev > 1e-6 {
            vDSP_normalize(normalizedAudio, 1, &normalizedAudio, 1, &mean, &stdDev, vDSP_Length(normalizedAudio.count))
        }
        
        let targetLength = 80000
        guard let mlArray = try? MLMultiArray(shape: [1, NSNumber(value: targetLength)], dataType: .float32) else { return nil }
        
        let ptr = mlArray.dataPointer.bindMemory(to: Float.self, capacity: targetLength)
        for i in 0..<targetLength {
            if i < normalizedAudio.count {
                ptr[i] = normalizedAudio[i]
            } else {
                ptr[i] = 0.0 // pad
            }
        }
        
        do {
            let input = Wav2Vec2_STTInput(audio: mlArray)
            let output = try self.acousticModel.prediction(input: input)
            return output.hidden_states
        } catch {
            print("Failed to extract hidden states: \(error)")
            return nil
        }
    }
    
    func extractLogProbs(_ mlArray: MLMultiArray, validFrames: Int) -> [[Float]] {
        let vocabSize = self.decoder.vocab.count
        var logProbs: [[Float]] = []
        let outFrames = mlArray.shape[1].intValue
        let frameStride = mlArray.strides[1].intValue
        let vocabStride = mlArray.strides[2].intValue
        
        let isFloat16 = mlArray.dataType == .float16
        let ptr16 = isFloat16 ? mlArray.dataPointer.bindMemory(to: Float16.self, capacity: mlArray.count) : nil
        let ptr32 = !isFloat16 ? mlArray.dataPointer.bindMemory(to: Float.self, capacity: mlArray.count) : nil
        
        let count = min(outFrames, validFrames)
        for f in 0..<count {
            var frameProbs: [Float] = []
            frameProbs.reserveCapacity(vocabSize)
            for v in 0..<vocabSize {
                let offset = f * frameStride + v * vocabStride
                let val = isFloat16 ? Float(ptr16![offset]) : ptr32![offset]
                frameProbs.append(val)
            }
            
            // Apply softmax
            let maxVal = frameProbs.max() ?? 0
            var sumExp: Float = 0
            for i in 0..<vocabSize {
                let expVal = exp(frameProbs[i] - maxVal)
                frameProbs[i] = expVal
                sumExp += expVal
            }
            for i in 0..<vocabSize {
                frameProbs[i] = log(frameProbs[i] / sumExp)
            }
            
            logProbs.append(frameProbs)
        }
        return logProbs
    }
    
    func decodeLogits(_ mlArray: MLMultiArray, validFrames: Int? = nil, reference: String? = nil) -> (snapped: String, literal: String, logProbs: [[Float]], topBeams: [String]) {
        let outFrames = mlArray.shape[1].intValue
        let count = min(outFrames, validFrames ?? outFrames)
        let logProbs = extractLogProbs(mlArray, validFrames: count)
        let decoded = self.decoder.decode(logProbs: logProbs, referenceText: reference, beamWidth: 30)
        return (snapped: decoded.snapped, literal: decoded.literal, logProbs: logProbs, topBeams: decoded.topBeams)
    }
}
